-- Target schema for MySQL 8 / MariaDB. Design artifact, not installed.
-- Store timestamps in UTC; display in Europe/Sofia. Monetary values: integer EUR cents.
CREATE TABLE users (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, name VARCHAR(160) NOT NULL, email VARCHAR(254) NOT NULL UNIQUE, password VARCHAR(255) NOT NULL, phone VARCHAR(40), role ENUM('admin','editor','user') NOT NULL DEFAULT 'user', status ENUM('active','frozen') NOT NULL DEFAULT 'active', email_verified_at DATETIME NULL, avatar_path VARCHAR(255), created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL);
CREATE TABLE user_internal_notes (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, user_id BIGINT UNSIGNED NOT NULL, author_id BIGINT UNSIGNED NOT NULL, body TEXT NOT NULL, created_at DATETIME NOT NULL, FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(author_id) REFERENCES users(id));
CREATE TABLE help_types (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, title VARCHAR(160) NOT NULL, price_cents INT UNSIGNED NOT NULL, currency CHAR(3) NOT NULL DEFAULT 'EUR', active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE slots (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, psychologist_id BIGINT UNSIGNED NOT NULL, starts_at DATETIME NOT NULL, ends_at DATETIME NOT NULL, enabled BOOLEAN NOT NULL DEFAULT TRUE, UNIQUE KEY slot_start(psychologist_id,starts_at), CHECK(ends_at>starts_at), FOREIGN KEY(psychologist_id) REFERENCES users(id));
CREATE TABLE bookings (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, user_id BIGINT UNSIGNED NOT NULL, psychologist_id BIGINT UNSIGNED NOT NULL, original_slot_id BIGINT UNSIGNED NOT NULL, current_slot_id BIGINT UNSIGNED NOT NULL, help_type_id BIGINT UNSIGNED NOT NULL, original_starts_at DATETIME NOT NULL, current_starts_at DATETIME NOT NULL, status ENUM('pending','accepted','rejected','moved') NOT NULL DEFAULT 'pending', approval_state ENUM('pending','approved','rejected') NOT NULL DEFAULT 'pending', price_cents INT UNSIGNED NOT NULL, currency CHAR(3) NOT NULL DEFAULT 'EUR', public_note TEXT NULL, payment_method ENUM('undecided','package','stripe','onsite') NOT NULL DEFAULT 'undecided', payment_status ENUM('unpaid','paid','refunded') NOT NULL DEFAULT 'unpaid', approved_at DATETIME NULL, approved_by BIGINT UNSIGNED NULL, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(psychologist_id) REFERENCES users(id), FOREIGN KEY(original_slot_id) REFERENCES slots(id), FOREIGN KEY(current_slot_id) REFERENCES slots(id), FOREIGN KEY(help_type_id) REFERENCES help_types(id), FOREIGN KEY(approved_by) REFERENCES users(id));
-- Atomic ownership of a current slot. Pending verified requests also occupy a slot.
CREATE TABLE slot_claims (slot_id BIGINT UNSIGNED PRIMARY KEY, booking_id BIGINT UNSIGNED NOT NULL UNIQUE, FOREIGN KEY(slot_id) REFERENCES slots(id), FOREIGN KEY(booking_id) REFERENCES bookings(id));
CREATE TABLE booking_internal_notes (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, booking_id BIGINT UNSIGNED NOT NULL, author_id BIGINT UNSIGNED NOT NULL, body TEXT NOT NULL, created_at DATETIME NOT NULL, FOREIGN KEY(booking_id) REFERENCES bookings(id), FOREIGN KEY(author_id) REFERENCES users(id));
CREATE TABLE booking_changes (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, booking_id BIGINT UNSIGNED NOT NULL, actor_id BIGINT UNSIGNED NOT NULL, action VARCHAR(40) NOT NULL, old_slot_id BIGINT UNSIGNED NULL, new_slot_id BIGINT UNSIGNED NULL, created_at DATETIME NOT NULL, FOREIGN KEY(booking_id) REFERENCES bookings(id), FOREIGN KEY(actor_id) REFERENCES users(id));
CREATE TABLE packages (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, title VARCHAR(160) NOT NULL, credits INT UNSIGNED NOT NULL, price_cents INT UNSIGNED NOT NULL, currency CHAR(3) NOT NULL DEFAULT 'EUR', active BOOLEAN NOT NULL DEFAULT TRUE, CHECK(credits>0));
CREATE TABLE events (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, psychologist_id BIGINT UNSIGNED NOT NULL, title VARCHAR(160) NOT NULL, description TEXT NOT NULL, price_cents INT UNSIGNED NOT NULL, currency CHAR(3) NOT NULL DEFAULT 'EUR', capacity INT UNSIGNED NULL, small_image_path VARCHAR(255), large_image_path VARCHAR(255), status ENUM('draft','published','cancelled') NOT NULL DEFAULT 'draft', FOREIGN KEY(psychologist_id) REFERENCES users(id));
CREATE TABLE event_sessions (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, event_id BIGINT UNSIGNED NOT NULL, starts_at DATETIME NOT NULL, ends_at DATETIME NOT NULL, FOREIGN KEY(event_id) REFERENCES events(id), CHECK(ends_at>starts_at));
CREATE TABLE orders (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, user_id BIGINT UNSIGNED NOT NULL, total_cents INT UNSIGNED NOT NULL, currency CHAR(3) NOT NULL DEFAULT 'EUR', status ENUM('pending','paid','cancelled','refunded') NOT NULL DEFAULT 'pending', payment_method ENUM('stripe','onsite') NOT NULL, created_at DATETIME NOT NULL, FOREIGN KEY(user_id) REFERENCES users(id));
-- Snapshot product title, unit price and credit entitlement at order creation.
CREATE TABLE order_items (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, order_id BIGINT UNSIGNED NOT NULL, package_id BIGINT UNSIGNED NULL, event_id BIGINT UNSIGNED NULL, booking_id BIGINT UNSIGNED NULL, title VARCHAR(160) NOT NULL, unit_price_cents INT UNSIGNED NOT NULL, quantity INT UNSIGNED NOT NULL DEFAULT 1, package_credits INT UNSIGNED NULL, FOREIGN KEY(order_id) REFERENCES orders(id), FOREIGN KEY(package_id) REFERENCES packages(id), FOREIGN KEY(event_id) REFERENCES events(id), FOREIGN KEY(booking_id) REFERENCES bookings(id), CHECK(quantity>0), CHECK((package_id IS NOT NULL)+(event_id IS NOT NULL)+(booking_id IS NOT NULL)=1));
CREATE TABLE user_packages (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, user_id BIGINT UNSIGNED NOT NULL, package_id BIGINT UNSIGNED NOT NULL, order_item_id BIGINT UNSIGNED NOT NULL UNIQUE, total_credits INT UNSIGNED NOT NULL, remaining_credits INT UNSIGNED NOT NULL, activated_at DATETIME NOT NULL, expires_at DATETIME NULL, FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(package_id) REFERENCES packages(id), FOREIGN KEY(order_item_id) REFERENCES order_items(id), CHECK(remaining_credits<=total_credits));
CREATE TABLE package_ledger (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, user_package_id BIGINT UNSIGNED NOT NULL, booking_id BIGINT UNSIGNED NOT NULL, action ENUM('debit','refund') NOT NULL, created_at DATETIME NOT NULL, UNIQUE KEY credit_once(booking_id,action), FOREIGN KEY(user_package_id) REFERENCES user_packages(id), FOREIGN KEY(booking_id) REFERENCES bookings(id));
CREATE TABLE event_registrations (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, event_id BIGINT UNSIGNED NOT NULL, user_id BIGINT UNSIGNED NOT NULL, order_item_id BIGINT UNSIGNED NOT NULL UNIQUE, status ENUM('pending','accepted','rejected','moved') NOT NULL DEFAULT 'pending', original_starts_at DATETIME NOT NULL, current_starts_at DATETIME NOT NULL, public_note TEXT NULL, UNIQUE KEY event_user(event_id,user_id), FOREIGN KEY(event_id) REFERENCES events(id), FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(order_item_id) REFERENCES order_items(id));
CREATE TABLE payments (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, order_id BIGINT UNSIGNED NOT NULL, provider ENUM('stripe','onsite') NOT NULL, provider_reference VARCHAR(255) NULL UNIQUE, amount_cents INT UNSIGNED NOT NULL, currency CHAR(3) NOT NULL DEFAULT 'EUR', status ENUM('pending','paid','failed','refunded') NOT NULL DEFAULT 'pending', received_at DATETIME NULL, recorded_by BIGINT UNSIGNED NULL, FOREIGN KEY(order_id) REFERENCES orders(id), FOREIGN KEY(recorded_by) REFERENCES users(id));
CREATE TABLE webhook_receipts (provider_event_id VARCHAR(255) PRIMARY KEY, received_at DATETIME NOT NULL, processed_at DATETIME NULL);
CREATE TABLE pages (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, slug VARCHAR(160) NOT NULL UNIQUE, title VARCHAR(160) NOT NULL, body LONGTEXT NOT NULL, status ENUM('draft','published') NOT NULL DEFAULT 'draft', updated_by BIGINT UNSIGNED NOT NULL, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, FOREIGN KEY(updated_by) REFERENCES users(id));
CREATE TABLE media (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, uploader_id BIGINT UNSIGNED NOT NULL, path VARCHAR(255) NOT NULL, mime_type VARCHAR(100) NOT NULL, size_bytes BIGINT UNSIGNED NOT NULL, alt_text VARCHAR(255), created_at DATETIME NOT NULL, FOREIGN KEY(uploader_id) REFERENCES users(id));
CREATE TABLE pending_registrations (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, email VARCHAR(254) NOT NULL, payload_encrypted TEXT NOT NULL, verification_token_hash CHAR(64) NOT NULL UNIQUE, expires_at DATETIME NOT NULL, verified_at DATETIME NULL);
CREATE TABLE audit_logs (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, actor_id BIGINT UNSIGNED NULL, action VARCHAR(100) NOT NULL, entity_type VARCHAR(80) NOT NULL, entity_id BIGINT UNSIGNED NULL, metadata JSON NULL, created_at DATETIME NOT NULL, FOREIGN KEY(actor_id) REFERENCES users(id));
CREATE TABLE settings (setting_key VARCHAR(100) PRIMARY KEY, value_json JSON NOT NULL, updated_by BIGINT UNSIGNED NULL, FOREIGN KEY(updated_by) REFERENCES users(id));
-- Laravel framework migrations also provide sessions, password reset tokens, jobs and failed_jobs.
-- Overlap checks, role checks, CSRF, transaction locks and note serialization belong to server policies/services.

CREATE TABLE event_registration_internal_notes (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, registration_id BIGINT UNSIGNED NOT NULL, author_id BIGINT UNSIGNED NOT NULL, body TEXT NOT NULL, created_at DATETIME NOT NULL, FOREIGN KEY(registration_id) REFERENCES event_registrations(id), FOREIGN KEY(author_id) REFERENCES users(id));
